messages.content:
{
  "message": "Thanks for the details. Since your status bar shows “No Signal” and data is OFF (with no Airplane Mode icon), this points to either (a) a line/account issue (suspension, SIM/eSIM change) or (b) a device-side radio/SIM issue. I’ll verify your line on our side, and in parallel let’s run a few quick checks on the phone to restore service.",
  "why_these_steps": "We must rule out Airplane Mode/SIM/network-mode issues on the device, and also check if your line is suspended or otherwise inactive on the network.",
  "need_verification": [
    "Phone number of the affected line (preferred). If unavailable, provide your Customer ID, or your full name + date of birth (YYYY-MM-DD).",
    "Are you currently traveling outside your usual area or abroad?",
    "Any recent changes (new phone/SIM/eSIM transfer, plan change, or bill/payment issues)?"
  ],
  "on_device_steps": [
    {
      "step": "Refresh radios",
      "do": "Toggle Airplane Mode ON for 10 seconds, then OFF.",
      "why": "Forces the cellular modem to re-register on the network."
    },
    {
      "step": "Check SIM status",
      "do": "Run check_sim_status and tell me if it shows Active, Missing, or Locked.",
      "what_if": {
        "Missing": "Run reseat_sim_card, then run reboot_device.",
        "Locked": "Do not guess the PIN. Tell me it’s locked—we’ll handle SIM security.",
        "Active": "Proceed to the next steps."
      }
    },
    {
      "step": "Confirm network and data switches",
      "do": "Run check_network_status. If Mobile Data is OFF, turn it ON using toggle_data. Confirm signal strength result (none/poor/fair/good/excellent).",
      "why": "Ensures the data toggle isn’t blocking registration tests and tells us whether the phone can see any cell signal."
    },
    {
      "step": "Optimize network mode",
      "do": "Run check_network_mode_preference. If it’s set to 2G or 3G, change it to set_network_mode_preference = \"4g_5g_preferred\".",
      "why": "Older modes can prevent modern network attach and cause ‘No Service’ in some areas."
    },
    {
      "step": "Reboot",
      "do": "Run reboot_device once the above are done.",
      "why": "Clears temporary radio/stack glitches and applies configuration changes."
    }
  ],
  "next_on_our_side": "As soon as you share your phone number (or other ID), I will check your line’s status (e.g., suspension, contract status, roaming setting) and resolve anything account-side. If you are abroad, I will also ensure roaming is enabled on your line.",
  "please_reply_with": [
    "Your phone number (or Customer ID / name + DOB) for verification.",
    "Results of check_sim_status (Active/Missing/Locked).",
    "Results of check_network_status (signal strength, network type, data enabled?).",
    "Your current location (home area or traveling/abroad)."
  ]
}

