messages.content:
{
  "message": "I can help you get mobile data working well while you’re abroad in France. To fix this, we’ll do two things in parallel: (1) check and optimize settings on your phone, and (2) check your line on our side (roaming status and data allowance).",
  "thought_process": "When traveling, mobile data depends on two layers: your phone’s settings (Data/Roaming/Network mode/VPN/Data Saver) and your line’s roaming and data status with us. If either layer blocks or limits data, you can see slow speeds or no connection. We’ll verify both and adjust as needed.",
  "need_from_you_to_identify": "For security and to check your line’s roaming and data status, please provide ONE of the following:",
  "acceptable_identifiers": [
    "Your mobile phone number (recommended)",
    "Your customer ID",
    "Your full name AND date of birth (YYYY-MM-DD)"
  ],
  "additional_questions": [
    "What phone are you using (iPhone or Android) and model (if known)?",
    "Roughly where in France are you right now (city/area)?",
    "Do you see any VPN icon or app connected?",
    "Have you noticed any ‘Data Saver’ or ‘Low Data Mode’ turned on?"
  ],
  "permission_request": "If your line’s international roaming is OFF, do I have your permission to enable roaming at no cost so you can use data in France?",
  "on_device_checks_and_fixes": [
    {
      "step": "Check quick status indicators",
      "why": "Airplane Mode, low signal, or 2G/3G can stop or slow data.",
      "ask_to_report_back": "Tell me what you see at the top of your screen: any airplane icon, how many signal bars, and the network type indicator (5G/LTE/4G/3G/E/2G)."
    },
    {
      "step": "Ensure Mobile Data and Data Roaming are ON",
      "why": "Abroad, Data Roaming must be ON for data to work.",
      "iphone": "Settings > Cellular/Mobile Data > turn ON ‘Cellular/Mobile Data’ and turn ON ‘Data Roaming’.",
      "android": "Settings > Network & Internet (or Connections) > Mobile network > turn ON ‘Mobile data’ and turn ON ‘Data roaming’."
    },
    {
      "step": "Disable VPN (if active)",
      "why": "Some VPNs cause very slow or no data on roaming networks.",
      "iphone": "Settings > VPN & Device Management (or General > VPN) > turn VPN OFF.",
      "android": "Settings > Network & Internet > VPN > disconnect/turn OFF."
    },
    {
      "step": "Turn OFF Data Saver / Low Data Mode",
      "why": "Data Saver can throttle or block background data and make apps seem stalled.",
      "iphone": "Settings > Cellular/Mobile Data > Data Mode > choose ‘Standard’ (not Low Data Mode).",
      "android": "Settings > Network & Internet > Data Saver > turn OFF."
    },
    {
      "step": "Use modern network mode (prefer 4G/5G)",
      "why": "2G/3G are too slow for modern apps; 4G/5G gives best speeds.",
      "iphone": "Settings > Cellular/Mobile Data > Voice & Data > choose 5G Auto (or LTE).",
      "android": "Settings > Mobile network > Preferred network type > select 5G/4G (LTE) preferred."
    },
    {
      "step": "Refresh the connection",
      "why": "Forces the phone to re-register on the local network.",
      "instructions": "Toggle Airplane Mode ON for 10 seconds, then OFF. If still poor after the above, please also restart the phone."
    }
  ],
  "what_I_will_check_on_our_side_after_identification": [
    "Confirm your line is active and not suspended.",
    "Verify international data roaming is enabled on your line; enable it if it isn’t (no cost).",
    "Check your plan’s monthly data limit and your current usage to see if you’ve hit the cap.",
    "If you’ve run out of high-speed data, I can add up to 2 GB of data (charged at your plan’s refuel rate) or help switch to a higher-data plan if you prefer."
  ],
  "next_actions": "Please reply with your phone number (or other identifier) and the answers/results from the on-device checks. I’ll then immediately verify your line’s roaming and data status and take the necessary steps to restore excellent speeds."
}

