    {
      "step": "Ensure Mobile Data is ON",
      "reason": "Data won’t work if the main switch is off.",
      "how": "Open Settings > Mobile/Cellular > turn Mobile Data/Cellular Data ON."
    },
    {
      "step": "Enable Data Roaming",
      "reason": "Abroad, data requires the Data Roaming toggle ON.",
      "how": "Settings > Mobile/Cellular > Cellular Data Options > turn Data Roaming ON."
    },
    {
      "step": "Disable VPN (if any)",
      "reason": "VPNs can cause very slow or failing data while roaming.",
      "how": "If a VPN key/lock icon shows, turn VPN OFF in Settings."
    },
    {
      "step": "Turn OFF Data Saver/Low Data Mode",
      "reason": "These modes can throttle/limit background data.",
      "how": "Settings > Network/Cellular > Data Saver (Android) OFF, or Settings > Cellular > Low Data Mode (iPhone) OFF."
    },
    {
      "step": "Network mode preference",
      "reason": "For best speeds, phone should allow 4G/5G.",
      "how": "Settings > Mobile/Cellular > Preferred network type: choose 4G/5G preferred (avoid 2G/3G only)."
    },
    {
      "step": "Quick refresh",
      "reason": "Forces a fresh network attach while roaming.",
      "how": "Toggle Airplane Mode ON for 10 seconds, then OFF. Wait 1–2 minutes."
    },
    {
      "step": "Speed test (if possible)",
      "reason": "Confirms data is flowing and how fast.",
      "how": "If pages now load, run any speed test app/site and tell me the result. If it fails, note the error (e.g., ‘no connection’)."
    }
  ],
  "next_steps_on_our_side": "Once you share your phone number, I’ll check your line’s roaming setting and current data usage. If roaming is disabled, I’ll enable it for free. If you’re out of high‑speed data, I’ll present refuel options (max 2 GB) with exact pricing for approval before applying.",
  "please_reply_with": [
    "Your phone number.",
    "Whether you completed the steps above and what you observed (signal bars, network type like 4G/5G, if Data Roaming was OFF/ON, VPN/Data Saver status).",
    "If you could run a speed test, the result; if not, what error you saw.",
    "Whether calls/SMS work."
  ]
}

