messages.content:
{
  "message": "Thanks for the update. Since Airplane Mode is OFF and you still see No Signal and Data Disabled, we’ll do two things in parallel: verify your line on our side and walk through a few quick device checks that commonly restore service.",
  "why_these_steps": "No signal after disabling Airplane Mode is typically caused by a SIM issue, mobile data being OFF, an unsuitable network mode (e.g., 2G), incorrect APN settings, roaming configuration, or an account/line suspension. We’ll rule these out in order.",
  "need_to_identify_you": "Please share ONE of the following so I can check your line status and roaming/suspension on the account:",
  "acceptable_ids": [
    "Affected phone number (preferred)",
    "OR your customer ID",
    "OR full name AND date of birth (YYYY-MM-DD)"
  ],
  "also_useful_context": [
    "Are you currently traveling outside your usual area/country? If yes, where are you now?",
    "Phone make/model and whether it’s a physical SIM or eSIM"
  ],
  "steps_for_your_device": [
    {
      "step": "Turn Mobile Data ON",
      "how": "Use the quick settings or Settings > Cellular/Mobile Data and switch Mobile Data ON.",
      "observe": "Wait up to 30 seconds. Do any signal bars or a network label (4G/LTE/5G) appear? Does Data Enabled show up?",
      "reason": "Mobile data being OFF will keep data disabled and sometimes delays network registration."
    },
    {
      "step": "Check SIM Status",
      "how": "Open Settings > About/Status > SIM status (wording varies). Tell me if it shows Active, Missing, or Locked.",
      "actions_based_on_result": {
        "Active": "Great—move to the next step.",
        "Missing": "If you use a physical SIM: power off, remove and reinsert the SIM, then power on. If eSIM shows Missing, just tell me—it may be an activation issue we’ll handle on the account side.",
        "Locked": "Do not guess the PIN/PUK. Tell me immediately so I can escalate for SIM unlock assistance."
      },
      "reason": "If the SIM isn’t detected or is locked, the phone cannot register on the network."
    },
    {
      "step": "Ensure Preferred Network Mode is modern",
      "how": "Settings > Cellular/Network > Preferred network type. If it shows 2G/3G, change to 4G/LTE/5G (e.g., “4g_5g_preferred”).",
      "reason": "Older modes can prevent proper registration and data."
    },
    {
      "step": "Verify APN (data/MMS) settings",
      "how": "Settings > Cellular > Access Point Names. If you see APN marked Incorrect or MMSC missing/blank, choose Reset to default.",
      "after_reset": "Reboot the phone once to apply APN changes.",
      "reason": "Incorrect APN can block data and sometimes affect network attach."
    },
    {
      "step": "Reboot if still no signal",
      "how": "Restart the device once after the above changes.",
      "reason": "A fresh network attach often restores service after settings changes."
    }
  ],
  "what_i_will_check_once_identified": [
    "Line status (Active vs Suspended) and any billing holds",
    "International roaming eligibility if you’re traveling",
    "Recent SIM/eSIM or activation events that might affect service"
  ],
  "please_reply_with": [
    "Your identifying info (phone number/customer ID/full name + DOB)",
    "Your current location (city/state/country) if traveling",
    "Phone model and SIM type (physical/eSIM)",
    "Results of each step above, especially SIM status and what the status bar shows after turning Mobile Data ON"
  ]
}

