      "instructions": [
        "Go to Settings > Network & Internet (or Connections) > SIMs or Mobile network.",
        "If you have dual SIMs, make sure the mobile data SIM is set to the line ending in 2002.",
        "Turn ‘Mobile data’ ON. If already ON, toggle OFF, wait 10 seconds, then ON again."
      ],
      "expected_result": "Status bar should no longer show data disabled."
    },
    {
      "title": "Set Preferred Network Type to 4G/5G",
      "instructions": [
        "In Settings > Network & Internet > Mobile network (or SIM settings) > Preferred network type:",
        "Select ‘5G (recommended)’ or ‘4G/5G preferred’. If those aren’t options, choose ‘LTE/3G/2G (auto)’—avoid any ‘2G only’ setting."
      ],
      "expected_result": "Status bar should show LTE/4G/5G instead of 2G once it reconnects."
    },
    {
      "title": "Turn Off Data Saver and VPN (if any)",
      "instructions": [
        "Settings > Network & Internet > Data Saver > turn OFF.",
        "Settings > Network & Internet > VPN > disconnect any active VPN."
      ],
      "reason": "These can block or slow mobile data."
    },
    {
      "title": "Test Mobile Data",
      "instructions": [
        "Turn Wi‑Fi OFF and try loading a website in your browser."
      ],
      "expected_result": "A page should load over mobile data."
    },
