    },
    {
      "title": "Grant media permission to the messaging app",
      "instructions": [
        "Settings > Apps > See all apps > messaging (your SMS app) > Permissions.",
        "If you see “Photos and videos” (Android 13+): set to Allow.",
        "If you see “Storage” or “Files and media” (older Android): set to Allow."
      ],
      "reason": "Lets the app read the photo you’re trying to send via MMS."
    },
    {
      "title": "Enable background/unrestricted data for the app",
      "instructions": [
        "In the same App info screen: Mobile data & Wi‑Fi (or Data usage).",
        "Turn ON Background data.",
        "Turn ON Unrestricted data usage."
      ],
      "reason": "Prevents Data Saver or OS from blocking MMS data calls."
    },
    {
      "title": "Verify Data Saver is OFF",
      "instructions": [
        "Settings > Network & Internet (or Connections) > Data Saver > OFF."
      ]
    },
