      ],
      "expected_result": "The picture should send successfully."
    },
    {
      "title": "If web works but MMS still fails: reset APN and reboot",
      "instructions": [
        "Settings > Network & Internet > Mobile network > Access Point Names (APN) > menu (⋮) > Reset to default.",
        "Restart the phone (power off, wait 15 seconds, power on).",
        "After reboot, confirm Mobile data is ON and Preferred network is 4G/5G, then retry website and MMS."
      ],
      "reason": "Restores the MMSC/APN settings MMS relies on."
    }
