messages.content:
{
  "summary": "I can help you get mobile data working at excellent speeds while you’re roaming in France. We’ll check both your phone settings and your line’s account settings (like roaming and data limits).",
  "plan": [
    "Identify your account so I can verify/enable roaming on your line and check if you’ve hit a data cap.",
    "Guide you through quick on-device checks to restore a fast data connection.",
    "If needed, adjust line settings (e.g., enable roaming) and discuss options like data refuel."
  ],
  "need_from_you_to_identify": {
    "choose_one": [
      "Phone number on the line (preferred)",
      "Customer ID",
      "Full name + date of birth (YYYY-MM-DD)"
    ]
  },
