    {
      "action": "check_network_status",
      "what_to_share_back": [
        "Airplane mode: ON/OFF",
        "Signal strength: none/poor/fair/good/excellent",
        "Network type: 5G/4G/3G/2G",
        "Mobile data: Enabled/Disabled",
        "Data roaming: ON/OFF"
      ],
      "why": "Confirms that mobile data and data roaming are ON and you have usable signal while abroad."
    },
