  "thought_process": "Given you have excellent 5G signal, mobile data ON, and roaming ON, but still get “No Connection,” the two most likely causes are: (1) incorrect APN settings on the phone (very common when roaming) or (2) an account-side block (roaming not enabled on your line or you hit your data cap). We’ll fix APN settings and refresh the data session now, and I’ll also check your line on our side once you identify your account.",
  "on_device_next_steps": [
    {
      "step": 1,
      "action": "check_apn_settings",
      "instruction": "Please check your APN settings and tell me: (a) the APN name and (b) whether an MMSC URL is shown.",
      "why": "An incorrect/missing APN or MMSC often causes total data failure while roaming."
    },
    {
      "step": 2,
      "action": "reset_apn_settings",
      "instruction": "If anything looks unfamiliar or you’re unsure, go ahead and reset APN to default now.",
      "why": "Restores the correct carrier settings that enable data while abroad."
    },
    {
      "step": 3,
      "action": "reboot_device",
      "instruction": "Immediately after resetting APN, reboot your phone.",
      "why": "A reboot applies the new APN settings cleanly."
    },
    {
      "step": 4,
      "action": "run_speed_test",
      "instruction": "After the reboot, run a speed test and share the result (unknown/very poor/poor/fair/good/excellent).",
      "why": "Confirms if data connectivity is restored."
    },
    {
      "step": 5,
      "action": "check_network_status",
      "instruction": "Share the updated status: signal strength, network type (expect 4G/5G), mobile data ON, and data roaming ON.",
      "why": "Verifies you’re attached to a high-speed network with roaming active."
    },
    {
      "step": 6,
      "action": "toggle_airplane_mode",
      "instruction": "If the speed test still shows ‘No Connection’, turn Airplane Mode ON for 20 seconds, then OFF, wait 1–2 minutes and re-test.",
      "why": "Forces a fresh registration to the roaming network."
    },
    {
      "step": 7,
      "action": "reseat_sim_card",
      "instruction": "If still no data, reseat the SIM (power off, remove SIM, reinsert carefully, power on) and re-test.",
      "why": "Eliminates any SIM contact/registration glitch."
    }
  ],
  "quick_questions": [
    "Right now, can you place and receive regular phone calls and SMS texts?",
    "After disabling the VPN earlier, is it still OFF?"
  ],
  "account_verification_needed": {
    "why": "I need to verify that roaming is enabled on your line at the carrier level and check if you reached your plan’s data limit (which would cut off data). If roaming is disabled or you’re out of data, I can fix/advise immediately.",
    "please_provide_one": [
      "Phone number on the affected line (preferred)",
      "Customer ID",
      "Full name + date of birth (YYYY-MM-DD)"
    ],
    "consent": "Do I have your permission to enable roaming on your line at no cost if it’s disabled, and to check your current data usage versus your plan limit?"
  },
  "next_step": "Please proceed with steps 1–5 (APN reset + reboot, then speed test and status). Share the results and your account identifier. With your permission, I’ll check and, if needed, enable roaming on your line and verify you haven’t hit a data cap."
}

