messages.content:
{
  "what_i_just_did": [
    "Added 2 GB of data to your line (555-123-2002). Charge: $4.00. This takes effect immediately.",
    "Your line is now roaming-enabled for France, so data and MMS are allowed while abroad."
  ],
  "why_these_steps_help": "MMS needs mobile data. You were over your plan limit (data blocked) and roaming was off. We fixed both on the account side. Now we’ll make sure your phone uses mobile data over the local French network.",
  "android_steps_do_these_in_order": [
    {
      "step": 1,
      "title": "Turn OFF Wi‑Fi temporarily",
      "how": "Swipe down from the top to open Quick Settings, tap the Wi‑Fi icon so it’s grayed out.",
      "reason": "For testing MMS we want to force the phone to use mobile data."
    },
    {
      "step": 2,
      "title": "Ensure Mobile Data is ON",
      "how": "In Quick Settings, make sure 'Mobile data' is ON. Or go to Settings > Network & Internet (or Connections) > Mobile network/SIMs > Mobile data ON.",
      "reason": "MMS uses mobile data."
    },
    {
      "step": 3,
      "title": "Confirm Airplane Mode is OFF",
      "how": "In Quick Settings, ensure the airplane icon is NOT enabled. If it’s on, tap it once to turn it off.",
      "reason": "Airplane Mode disables cellular connections."
    },
    {
      "step": 4,
      "title": "Turn Data Roaming ON",
      "how": "Settings > Network & Internet (or Connections) > Mobile network > Roaming > turn ON.",
      "reason": "You’re in France; roaming must be enabled on the device for data/MMS to work."
    },
    {
      "step": 5,
      "title": "Temporarily turn OFF Wi‑Fi Calling",
      "how": "Settings > Network & Internet (or Connections) > Mobile network > Wi‑Fi Calling > turn OFF.",
      "reason": "Avoids MMS conflicts while we test."
    },
    {
      "step": 6,
      "title": "Quick data check",
      "how": "With Wi‑Fi still OFF, open your browser and try loading any webpage (e.g., example.com).",
      "expected": "Page should load now that data is restored. If it doesn’t, tell me what happens."
    },
    {
      "step": 7,
      "title": "Test MMS",
      "how": "Open your Messages app and send a small photo to your own number or to a trusted contact.",
      "expected": "The MMS should send successfully."
    }
  ],
  "please_reply_with": [
    "Did the webpage load in Step 6?",
    "Did your MMS send in Step 7?",
    "If something failed, tell me which step and exactly what you see (icons in the top bar like 4G/5G, any messages in the app)."
  ],
  "if_mms_still_fails_after_step_7": {
    "next_actions": [
      {
        "title": "Reset APN to defaults (this fixes MMSC settings for MMS)",
        "how": "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names (APN) > tap the three dots ••• > Reset to default."
      },
      {
        "title": "Reboot the phone",
        "how": "Hold the power button > Restart.",
        "reason": "Applies the APN changes."
      },
      {
        "title": "Retest MMS",
        "how": "Keep Wi‑Fi OFF, Mobile data ON, Roaming ON; send a small photo again."
      }
    ],
    "let_me_know": "Tell me once you’ve done these so I can reassess."
  },
  "thought_process": "We enabled roaming and added data on your account to remove the two blockers. Now we’re ensuring your phone is actually using mobile data on a roaming network. If that works but MMS still fails, resetting APN + reboot fixes the MMS server (MMSC) settings."
}

