  "if_still_on_2g_or_mms_fails": [
    {
      "title": "Reset APN to defaults",
      "how": "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names (APN) > menu (•••) > Reset to default."
    },
    {
      "title": "Reboot the phone",
      "how": "Hold the power button > Restart. Keep Wi‑Fi OFF, Mobile Data ON, and Data Roaming ON, then test MMS again."
    }
  ],
  "thought_process": "We already enabled roaming and added data. Now we’re ensuring your device connects using a suitable network type. If APN settings are off, resetting them plus a reboot will restore the MMS server (MMSC) settings."
