messages.content:
{
  "what_this_means": "You’re seeing strong 5G but have no data. That usually points to a device-side setting (roaming/VPN/Data Saver), APN/MMSC config, or a roaming network compatibility issue. We’ll fix these in order.",
  "steps_on_android_in_order": [
    {
      "step": 1,
      "title": "Confirm Data Roaming is ON",
      "how": "Settings > Network & Internet (or Connections) > Mobile network > Data roaming > turn ON.",
      "why": "Required to use data abroad."
    },
    {
      "step": 2,
      "title": "Turn OFF any VPN",
      "how": "Settings > Network & Internet > VPN > disconnect/turn OFF.",
      "why": "VPNs can block data during setup or roaming."
    },
    {
      "step": 3,
      "title": "Turn OFF Data Saver",
      "how": "Settings > Network & Internet > Data Saver > turn OFF.",
      "why": "Can interfere with background data needed for MMS."
    },
    {
      "step": 4,
      "title": "Temporarily force LTE/4G",
      "how": "Settings > Network & Internet (or Connections) > Mobile network (or SIMs) > Preferred network type > choose LTE/4G only (or LTE/3G/2G Auto if LTE-only isn’t available).",
      "why": "Some roaming partners don’t pass data on 5G; LTE is more reliable."
    },
    {
      "step": 5,
      "title": "Reset APN to defaults",
      "how": "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names (APN) > menu (•••) > Reset to default.",
      "why": "Restores correct APN and MMSC settings needed for data/MMS."
    },
    {
      "step": 6,
      "title": "Reboot the phone",
      "how": "Hold power > Restart.",
      "why": "Applies APN changes and refreshes network registration."
    },
    {
      "step": 7,
      "title": "Retest data and MMS",
      "how": "After reboot, keep Wi‑Fi OFF. Ensure Mobile data ON and Data roaming ON. Wait 30–60 seconds. Check top bar (look for 4G/LTE or 5G with ‘R’). Load a webpage, then send a small photo via Messages.",
      "expected": "Webpage should load; MMS should send within 5–15 seconds."
    }
  ],
  "if_still_no_data_after_step_7": [
    {
      "title": "Set Network selection to Automatic",
      "how": "Settings > Network & Internet (or Connections) > Mobile network > Network operators > Select automatically."
    },
    {
      "title": "Reseat the SIM",
      "how": "Power off, eject SIM carefully, wait 10 seconds, reinsert, power on. Then ensure Wi‑Fi OFF, Mobile data ON, Roaming ON, and retest."
    }
  ],
  "please_report_back": [
    "After Step 7, what does the top bar show (4G/LTE/5G, ‘R’)?",
    "Did a webpage load?",
    "Did the MMS send?",
    "If something failed, which step and what exactly happened?"
