messages.content:
{
  "intent": "optimize_mobile_data_speed_abroad",
  "current_state": {
    "line": "L1002",
    "roaming": "Enabled on our side",
    "device_status": "5G with excellent signal, but speed test = fair"
  },
  "reasoning": "Since you already have an excellent 5G signal, fair speeds usually point to device-side constraints (VPN/Data Saver), temporary network congestion on the local 5G cell, or suboptimal APN settings. We’ll remove possible software bottlenecks first, then compare 5G vs 4G performance, and finally validate APN.",
  "steps": [
    {
      "step": "Check VPN",
      "why": "Active VPNs can cap or route traffic inefficiently, lowering speed.",
      "actions_on_phone": [
        "Run check_vpn_status.",
        "If it shows VPN connected, run disconnect_vpn.",
        "Run run_speed_test again and share the rating."
      ]
    },
    {
      "step": "Check Data Saver",
      "why": "Data Saver can throttle or restrict background traffic, making performance feel slower.",
      "actions_on_phone": [
        "Run check_data_restriction_status.",
        "If Data Saver is ON, run toggle_data_saver_mode to turn it OFF.",
        "Run run_speed_test again and share the rating."
      ]
    },
    {
      "step": "Compare networks (5G vs 4G-only)",
      "why": "In some locations 5G cells are congested; 4G can actually be faster. We’ll test.",
      "actions_on_phone": [
        "Run set_network_mode_preference with mode=\"4g_only\".",
        "Wait ~20–30 seconds.",
        "Run check_network_status (confirm network type shows 4G).",
        "Run run_speed_test and share the rating.",
        "If 4G is faster (Good/Excellent), you can keep 4G-only for now. If not, switch back using set_network_mode_preference to \"4g_5g_preferred\"."
      ]
    },
    {
      "step": "Validate APN settings",
      "why": "Incorrect or stale APN can limit throughput, especially when roaming.",
      "actions_on_phone": [
        "Run check_apn_settings and tell me what it shows.",
        "If it looks incorrect/blank, run reset_apn_settings, then run reboot_device to apply.",
        "After reboot, run check_network_status and run_speed_test again."
      ]
    }
  ],
  "what_to_report_back": [
    "VPN status and the speed test rating after disconnecting (if it was on).",
    "Data Saver status and the speed test rating after turning it off (if it was on).",
    "Speed test rating on 4G-only vs 5G preferred, and which one is faster.",
    "APN details or confirmation that you reset APN and rebooted, plus the new speed test rating."
  ],
  "goal": "Achieve a speed test rating of Excellent. We’ll keep whichever mode (4G-only or 5G preferred) delivers the best performance where you are."
}

