messages.content:
{
  "result": "in_progress",
  "what_i_think_and_why": "No Signal + Data Disabled after reboot means the phone is not registered on a network and the mobile data switch is currently OFF at the device level. Since you previously had 4G signal in France and your line is active with roaming enabled on our side, the most likely causes now are: (1) SIM not recognized/locked, (2) device radio state needs a refresh, (3) mobile data is OFF on the device, (4) network mode preference needs correction, or (5) device roaming toggle needs to be ON.",
  "do_these_now_in_order": [
    {
      "step": "Check SIM status",
      "actions_on_your_device": [
        "Run: check_sim_status",
        "If it says Missing: run reseat_sim_card, then run reboot_device and try again after reboot.",
        "If it says Locked (PIN/PUK): stop and tell me. We’ll transfer you to a human agent to assist with SIM unlock.",
        "If it says Active: proceed to the next step."
      ]
    },
    {
      "step": "Check overall network state",
      "actions_on_your_device": [
        "Run: check_network_status",
        "If it shows Airplane Mode ON: run toggle_airplane_mode(to=\"off\").",
        "If it shows Mobile Data Disabled: run toggle_data(to=\"on\")."
      ]
    },
    {
      "step": "Force a clean network re-registration",
      "actions_on_your_device": [
        "Run: toggle_airplane_mode(to=\"on\"). Wait 10–15 seconds.",
        "Then run: toggle_airplane_mode(to=\"off\"). Wait ~30–60 seconds for signal bars to appear."
      ],
      "why": "This forces the radio to drop and reattach to an available roaming partner."
    },
    {
      "step": "Ensure the right network mode",
      "actions_on_your_device": [
        "Run: check_network_mode_preference",
        "If it shows 2G or 3G: run set_network_mode_preference(mode=\"4g_5g_preferred\")."
      ],
      "why": "2G/3G can prevent proper data/MMS; you need at least 3G and preferably 4G/5G."
    },
    {
      "step": "Confirm device roaming is ON",
      "actions_on_your_device": [
        "You mentioned it is ON, but let’s be sure: run toggle_roaming(to=\"on\")."
      ],
      "why": "Abroad, device-level Data Roaming must be ON for registration and data."
    },
    {
      "step": "If still No Signal after the above",
      "actions_on_your_device": [
        "Run: reseat_sim_card",
        "Then run: reboot_device",
        "After reboot, wait 1–2 minutes and check for signal bars."
      ],
      "why": "A reseat fixes many SIM recognition and radio attach issues."
    },
    {
      "step": "Test MMS again",
      "actions_on_your_device": [
        "With Wi‑Fi OFF, confirm Mobile Data shows Enabled in the status bar.",
        "Try sending an MMS.",
        "If it fails, run: can_send_mms() and share the result."
      ]
    }
  ],
  "tell_me": [
    "The exact result of check_sim_status (Active, Missing, or Locked).",
    "The readout from check_network_status (airplane mode, signal strength, network type, mobile data enabled, data roaming enabled).",
    "After doing the steps, whether signal bars returned and whether you could toggle Mobile Data to ON.",
    "If MMS still fails, the exact error and the result of can_send_mms().",
    "Your current city/area in France (optional, to consider local coverage with roaming partners if needed)."
  ]
}

