messages.content:
{
  "thought_process": "Your line is active and I enabled international roaming on our side. Since you still see “no signal” and “data disabled,” your phone hasn’t registered on a roaming network yet. The quickest fixes are to ensure device-side Mobile data + Data roaming are ON, then force a fresh registration via reboot. If still no signal, we’ll check SIM status and network mode.",
  "next_steps": [
    {
      "title": "Confirm Mobile data and Data roaming are ON (Android)",
      "why": "Both must be ON for data/MMS while abroad.",
      "how": [
        "Open Settings.",
        "Go to one that matches your phone:",
        "- Network & Internet > Mobile network (or SIMs) > [Your SIM]",
        "- Samsung: Connections > Mobile networks > [Your SIM]",
        "Turn ON: Data roaming.",
        "Turn ON: Mobile data (sometimes called Cellular data).",
        "Tip: You can also pull down Quick Settings and ensure the Mobile data tile is ON."
      ]
    },
    {
      "title": "Reboot the phone",
      "why": "Forces a fresh registration with a roaming partner network.",
      "how": [
        "Hold the power button and choose Restart (or Power off, then power on).",
        "After it boots, wait up to 2 minutes watching the status bar for signal bars and 4G/LTE/5G (often with an “R”)."
      ]
    },
    {
      "title": "Check SIM status",
      "why": "If the SIM isn’t recognized or is locked, you’ll see no signal.",
      "how": [
        "Settings > About phone > SIM status (or Settings > Network & Internet > SIMs > [Your SIM] > Status).",
        "Tell me exactly what it says (e.g., Active/Connected, No SIM, SIM not provisioned, SIM locked).",
        "If it shows Missing/Not detected: Power off, remove and reinsert the SIM firmly, then power on."
      ]
    },
    {
      "title": "Set Preferred network type to 4G/5G",
      "why": "Prevents being stuck on older modes that may not roam well.",
      "how": [
        "Settings > Network & Internet > Mobile network (or SIMs > [Your SIM]) > Preferred network type.",
        "Select: 4G/5G preferred (avoid 2G/3G)."
      ]
    }
  ],
  "once_signal_returns_test_mms": [
    "Turn Wi‑Fi OFF for the test (Quick Settings > tap Wi‑Fi so it’s off). Ensure Mobile data stays ON.",
    "Open the default Messages app.",
    "Start a new message to yourself or a trusted contact.",
    "Tap +/paperclip/camera, pick a small recent photo, and Send.",
    "Wait up to 60 seconds and note success or any error."
  ],
  "what_to_report_back": [
    "After the reboot, do you see signal bars and 4G/LTE/5G (maybe with an “R”)?",
    "Your SIM status text from the SIM status screen.",
    "Which Preferred network type is selected.",
    "Result of the MMS test once you have signal."
  ]
}

