messages.content:
{
  "thought_process": "Your line is active and I enabled international roaming on our side. To use MMS while abroad, your Android phone must have both Mobile data and Data roaming turned ON. I’ll guide you step by step. After enabling them, we’ll quickly test MMS.",
  "enable_mobile_data_android": {
    "quick_settings_method": [
      "Unlock your phone.",
      "Swipe down from the top to open Quick Settings.",
      "Find the Mobile data (or Cellular data) tile and tap it to turn it ON.",
      "For the MMS test later, turn Wi‑Fi OFF by tapping the Wi‑Fi tile so it’s off."
    ],
    "settings_app_method": {
      "generic": [
        "Open Settings.",
        "Go to Network & Internet (or Connections) > Mobile network (or SIMs).",
        "If you have multiple SIMs, tap the SIM for 555-123-2002.",
        "Turn ON Mobile data (or Cellular data)."
      ],
      "brand_examples": {
        "Samsung": "Settings > Connections > Mobile networks > turn ON Mobile data.",
        "Google Pixel/Stock Android": "Settings > Network & Internet > SIMs (or Mobile network) > [Your SIM] > turn ON Mobile data.",
        "OnePlus": "Settings > Wi‑Fi & Network > SIM & network > [Your SIM] > turn ON Mobile data."
      }
    }
  },
  "enable_data_roaming_android": {
    "steps": [
      "Open Settings.",
      "Go to the same place as above (Network & Internet > Mobile network or SIMs; Samsung: Connections > Mobile networks).",
      "Tap your active SIM if needed.",
      "Find Data roaming (may be called Roaming, International roaming, or Data while roaming) and turn it ON.",
      "If prompted with a warning, confirm/Allow."
    ],
    "tips": [
      "If you can’t find it, use the search bar in Settings and type roaming, then open Data roaming and enable it.",
      "If you have dual SIMs, ensure the correct SIM (555-123-2002) is selected when enabling these toggles."
    ]
  },
  "what_to_expect_after_enabling": [
    "Status bar should show signal bars and a 4G/LTE/5G icon, often with an R for roaming.",
    "If it still shows no signal, toggle Airplane mode ON for 10 seconds then OFF, or restart the phone once."
  ],
  "how_to_test_mms": [
    "With Wi‑Fi OFF and Mobile data + Data roaming ON, open your default Messages app.",
    "Start a new message to your own number or a trusted contact.",
    "Tap the +, paperclip, or camera icon and pick a small recent photo.",
    "Tap Send and wait up to 60 seconds. Note if it sends or shows an error."
  ],
  "if_toggles_are_missing_or_grayed_out": [
    "Use Settings search for Mobile data and Data roaming.",
    "Check SIM status: Settings > About phone > SIM status (or Settings > Network & Internet > SIMs > [Your SIM] > Status). Tell me exactly what it says (Active/Connected, No SIM, SIM locked, etc.).",
    "Ensure Airplane mode is OFF and try a full restart."
  ],
  "please_confirm": [
    "Which exact menu path did you use to turn ON Mobile data and Data roaming?",
    "After enabling them, what do you see in the status bar (signal bars, 4G/LTE/5G, R)?",
    "Did the photo MMS send successfully? If not, what error appears?"
  ],
  "next_if_still_no_signal": [
    "Set Preferred network type to 4G/5G: Settings > Network & Internet > Mobile network (or SIMs > [Your SIM]) > Preferred network type > choose 4G/5G preferred.",
    "If SIM status shows Missing/Not detected, power off, reseat the SIM, and power on; report back what you see."
  ]
}

