messages.content:
{
  "thought_process": "Your line is Active and I already enabled international roaming on our side. You’ve turned Mobile Data and Data Roaming ON on the phone, but there’s still no signal. That means the phone hasn’t registered with a roaming partner yet. The most likely causes now are: SIM not recognized/locked, network mode set to an incompatible option, or the device needs a deeper refresh. We’ll check SIM status, adjust network mode, refresh data, and if needed reseat the SIM and reset APN.",
  "step_1_check_sim_status_on_android": {
    "why": "If the SIM is missing/not detected or locked, the phone cannot connect to any network.",
    "how": [
      "Open Settings.",
      "Go to: Network & Internet (or Connections) > SIMs (or Mobile network) > [Your SIM] > Status. On some phones: Settings > About phone > SIM status.",
      "Read the SIM status and tell me exactly what it says: Active/Connected, No SIM, SIM not provisioned, SIM locked, etc."
    ],
    "what_to_do_based_on_result": [
      "If Active/Connected: proceed to Step 2.",
      "If No SIM/Missing/Not detected: Power off the phone, remove the SIM tray, reinsert the SIM firmly, power on, then re-check.",
      "If SIM locked (PIN/PUK): Do not guess codes. Tell me exactly what it shows so I can get this handled. We’ll transfer you to a human agent for SIM security if needed."
    ]
  },
  "step_2_set_preferred_network_type": {
    "why": "Being stuck on 2G/3G or an incompatible mode can prevent roaming registration.",
    "how": [
      "Open Settings.",
      "Go to Network & Internet > Mobile network (or SIMs > [Your SIM]).",
      "Tap Preferred network type (or Network mode).",
      "Select 4G/5G preferred (avoid 2G/3G)."
    ]
  },
  "step_3_refresh_mobile_data_switch": {
    "why": "Forces a data context rebuild.",
    "how": [
      "Pull down Quick Settings.",
      "Toggle Mobile data OFF, wait 10 seconds, then turn it back ON.",
      "Keep Data Roaming ON.",
      "Wait up to 1–2 minutes to see if signal bars and 4G/LTE/5G (often with an “R”) appear."
    ]
  },
  "step_4_reseat_sim_if_needed": {
    "when": "Only if Step 1 showed Missing/Not detected, or if Steps 2–3 didn’t help.",
    "how": [
      "Power off the phone completely.",
      "Eject the SIM tray, remove and reinsert the SIM card firmly (gold contacts down).",
      "Reinsert the tray and power the phone back on.",
      "Wait up to 2 minutes for signal to appear."
    ]
  },
  "step_5_reset_apn_then_reboot": {
    "why": "Incorrect APN can block registration/data on some devices. Reset ensures correct defaults.",
    "how_android": [
      "Open Settings > Network & Internet > Mobile network > Access Point Names.",
      "Open the menu (⋮) and tap Reset to default (or tap each carrier APN and choose Reset).",
      "After resetting, reboot the phone (Restart).",
      "Wait up to 2 minutes for signal and data icons to appear."
    ]
  },
  "once_signal_returns_test_mms": [
    "Turn Wi‑Fi OFF for the test (Quick Settings > toggle Wi‑Fi off). Ensure Mobile Data and Data Roaming are ON.",
    "Open the default Messages app.",
    "Start a new message to your own number or a trusted contact.",
    "Tap +/paperclip/camera, choose a small recent photo, and Send.",
    "Wait up to 60 seconds and note success or any error message."
  ],
  "please_report_back": [
    "What exact SIM status text do you see in Settings?",
    "Which Preferred network type is selected now?",
    "After toggling Mobile data and/or reseating the SIM, did any signal bars or a 4G/LTE/5G icon with an “R” appear?",
    "Result of the MMS test once you have signal (or any error text if it fails)."
  ],
  "note": "If your SIM shows as Locked (PIN/PUK) or if all steps above fail to produce any signal, I’ll transfer you to a human agent to investigate further and assist with SIM security or advanced roaming provisioning."
}

