      "step": 3,
      "action": "toggle_roaming",
      "how": "Turn Data Roaming ON in your phone settings.",
      "why": "You’re in France; the phone must allow data while roaming.",
      "what_to_check_after": "Check if a roaming indicator appears (often an 'R') and whether signal/data icons stabilize."
    },
    {
      "step": 4,
      "action": "check_network_mode_preference",
      "how": "Open your Network Mode/Preferred Network settings and see what it’s set to.",
