      "if_needed": {
        "action": "set_network_mode_preference",
        "mode": "4g_5g_preferred",
        "why": "Ensures the phone connects to modern networks suitable for MMS."
      }
    },
    {
      "step": 5,
      "action": "recheck_status_bar",
      "how": "After steps 1–4, look again at the icons.",
      "what_to_report": "Number of bars, exact network type label (3G/4G/LTE/5G), and whether an 'R' shows."
    },
    {
      "step": 6,
      "action": "quick_data_test",
      "how": "With Wi‑Fi still OFF, try loading a simple website (e.g., example.com).",
      "why": "Confirms mobile data is working while roaming, which MMS needs."
    },
    {
      "step": 7,
      "action": "test_mms",
      "how": "Open your Messages app and try sending a small photo to yourself.",
      "why": "Verifies MMS after reattaching to the network with data/roaming ON."
