      "step": 9,
      "action": "check_apn_settings (only if data works but MMS still fails)",
      "how": "Check APN and ensure MMSC URL is present.",
      "if_needed": {
        "action": "reset_apn_settings",
        "after": "reboot_device",
        "why": "Incorrect/missing MMSC is a common MMS failure cause. A reboot applies the reset."
      }
    },
    {
      "step": 10,
      "action": "check_wifi_calling_status (if MMS still fails)",
      "how": "If Wi‑Fi Calling is ON, toggle_wifi_calling OFF temporarily and retest MMS.",
      "why": "Some configurations interfere with MMS while roaming."
