  "thought_process": "MMS requires: (1) working mobile data (you have it), and (2) a correct MMSC URL in APN settings. Wi‑Fi Calling, Data Saver, or missing app permissions can also block MMS. We’ll verify/fix each of these.",
  "steps_on_your_phone": [
    {
      "step": 1,
      "action": "check_apn_settings",
      "how": "Check your APN and look for the MMSC (MMS server) field.",
      "what_to_look_for": "Is the MMSC URL present (not blank)?",
      "if_missing_or_uncertain": {
        "do": "reset_apn_settings",
        "after": "reboot_device",
        "why": "Resets to the carrier defaults, including the correct MMSC needed for MMS."
      }
    },
    {
      "step": 2,
      "condition": "After reboot (or if MMSC was already present)",
      "action": "check_wifi_calling_status",
      "how": "See if Wi‑Fi Calling is ON.",
      "if_on": {
        "do": "toggle_wifi_calling OFF",
        "why": "Some setups, especially while roaming, can interfere with MMS."
      }
    },
    {
      "step": 3,
      "action": "check_data_restriction_status",
      "how": "Verify Data Saver is OFF.",
      "if_on": {
        "do": "toggle_data_saver_mode OFF",
        "why": "Data Saver can block background data needed by MMS."
      }
    },
    {
