      "action": "check_app_permissions",
      "how": "Open the Messages app permissions.",
      "must_have": [
        "storage",
        "sms"
      ],
      "if_missing": {
        "do": [
          "grant_app_permission(app_name=\"messaging\", permission=\"storage\")",
          "grant_app_permission(app_name=\"messaging\", permission=\"sms\")"
        ],
        "why": "The app needs access to store and send media."
      }
    },
    {
      "step": 5,
      "action": "test_mms",
      "how": "With Wi‑Fi still OFF, send a small photo to your own number in Messages.",
