messages.content:
{
  "acknowledgement": "I’m ready to proceed and get this resolved.",
  "limitation": "I can’t run tests from here—you’ll need to perform them on your phone and share the results.",
  "thought_process": "To isolate the cause, we need your account details for backend checks (line status, data usage, roaming eligibility) while you run radio refresh steps on the phone. With good 5G signal but prior no-connection, the most effective next actions are Airplane Mode reset, testing a 4G-only fallback, enabling roaming if traveling, and reseating the SIM if needed.",
  "need_account_verification": {
    "message": "Please provide one of the following so I can check your line status, data usage, and roaming eligibility:",
    "acceptable_identifiers": [
      "Your mobile phone number (preferred)",
      "OR your Customer ID",
      "OR your full name AND date of birth (YYYY-MM-DD)"
    ]
  },
  "on_device_steps": [
    {
      "step": 1,
      "action": "Confirm Wi‑Fi is OFF and run a mobile‑data speed test.",
      "report": "Result: no connection / very poor / poor / fair / good / excellent."
    },
    {
      "step": 2,
      "condition": "If the result is no connection or below fair",
      "action": "Turn Airplane Mode ON for 15 seconds, then OFF. Wait 30 seconds and run the speed test again."
    },
    {
      "step": 3,
      "condition": "If still no connection or below fair",
      "action": "Change your network mode to 4g_only and test again."
    },
    {
      "step": 4,
      "condition": "If you are traveling outside your usual area or abroad",
      "action": "Turn Data Roaming ON and re‑run the speed test."
    },
    {
      "step": 5,
      "optional": true,
      "action": "If issues persist, power off the phone, remove and reinsert the SIM card, power on, and test again."
    }
  ],
  "please_report_back": [
    "Speed test result with Wi‑Fi OFF.",
    "Result after Airplane Mode reset (if done).",
    "Result after switching to 4g_only (if done).",
    "If traveling: result after turning Data Roaming ON.",
    "If you reseated the SIM: result afterward."
  ],
  "context_questions": [
    "Are you traveling outside your usual area or abroad right now?",
    "Is the slowness or no connection everywhere or only in certain places/times?",
    "Did this start recently after any change (new phone/SIM/settings)?",
    "Does it affect all apps or only specific ones?",
    "When you use Wi‑Fi, is it fast while mobile data is slow or no connection?"
  ],
  "next_backend_actions_after_id": [
    "Verify line status (active/suspended) and any account blocks.",
    "Check current cycle data usage vs. your plan limit.",
    "If out of data: offer a data refuel (up to 2 GB) or discuss plan options.",
    "If you’re traveling and roaming is disabled on your line: enable roaming at no cost.",
    "Re-test speed with you to confirm performance reaches good/excellent."
  ]
}

